+/*
+ * Copyright (c) Huawei Technologies Co., Ltd. 2026-2026. All rights reserved.
+ */
+
+package com.huawei.i2000.dvaiagentservice.business.intent;
+
+import org.junit.Test;
+
+import java.util.ArrayList;
+import java.util.HashMap;
+import java.util.Map;
+
+import static org.junit.Assert.assertEquals;
+
+/**
+ * 知识检索工具测试
+ *
+ * @since 2026-03-09
+ */
+public class KnowledgeQueryTest {
+    @Test
+    public void testExtractKnowledgeDataFromLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        properties.put("links", "2");
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("2", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataFromKnowledge() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataEmptyLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        properties.put("links", "");
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataNullLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataIncorrectLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        properties.put("links", new ArrayList<>());
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+}
