+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataEmptyLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        properties.put("links", "");
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataNullLink() {
+        KnowledgeRsp knowledgeRsp = new KnowledgeRsp();
+        knowledgeRsp.setKnowledge("1");
+        Map<String, Object> properties = new HashMap<>();
+        knowledgeRsp.setProperties(properties);
+
+        assertEquals("1", KnowledgeQuery.extractKnowledgeData(knowledgeRsp));
+    }
+
+    @Test
+    public void testExtractKnowledgeDataIncorrectLink() {
